-- Replace the legacy {cardBg,textColor,accentColor} contract with complete,
-- contrast-tested semantic tokens. Unknown/admin-authored themes are left
-- untouched and will remain unavailable to learners until an admin updates
-- them through the validated theme editor.
UPDATE learning.flashcard_style AS theme
SET config = semantic.config
FROM (
  VALUES
    ('minimal-ink', '{"background":"#ffffff","contentSurface":"#ffffff","foreground":"#111827","mutedForeground":"#4b5563","border":"#64748b","accent":"#1d4ed8","accentForeground":"#ffffff","controlBackground":"#111827","controlForeground":"#ffffff","focusRing":"#2563eb","fontFamily":"''Noto Sans JP'', sans-serif","borderRadius":"16px","flipAnimation":"rotateY","shadow":"0 4px 24px rgba(0,0,0,0.08)"}'::jsonb),
    ('warm-paper', '{"background":"#faf6f1","contentSurface":"#faf6f1","foreground":"#3d3225","mutedForeground":"#66543f","border":"#75634d","accent":"#92400e","accentForeground":"#ffffff","controlBackground":"#78350f","controlForeground":"#ffffff","focusRing":"#92400e","fontFamily":"''Noto Serif JP'', serif","borderRadius":"12px","flipAnimation":"rotateY","shadow":"0 2px 16px rgba(139,90,43,0.1)"}'::jsonb),
    ('dark-focus', '{"background":"#1e1e2e","contentSurface":"#1e1e2e","foreground":"#f8fafc","mutedForeground":"#cbd5e1","border":"#94a3b8","accent":"#c4b5fd","accentForeground":"#1e1e2e","controlBackground":"#f8fafc","controlForeground":"#1e1e2e","focusRing":"#c4b5fd","fontFamily":"''Inter'', ''Noto Sans JP'', sans-serif","borderRadius":"20px","flipAnimation":"rotateY","shadow":"0 8px 32px rgba(0,0,0,0.4)"}'::jsonb),
    ('sakura-bloom', '{"background":"linear-gradient(135deg, #fff5f7 0%, #ffe4ec 100%)","contentSurface":"#fff5f7","foreground":"#4a1942","mutedForeground":"#74405f","border":"#82536b","accent":"#9d174d","accentForeground":"#ffffff","controlBackground":"#9d174d","controlForeground":"#ffffff","focusRing":"#9d174d","overlay":"#fff5f7","fontFamily":"''Zen Maru Gothic'', ''Noto Sans JP'', sans-serif","borderRadius":"24px","flipAnimation":"rotateX","shadow":"0 8px 40px rgba(157,23,77,0.16)"}'::jsonb),
    ('neon-tokyo', '{"background":"linear-gradient(160deg, #0f0c29 0%, #302b63 50%, #24243e 100%)","contentSurface":"#17152b","foreground":"#f1f5f9","mutedForeground":"#c7d2fe","border":"#94a3b8","accent":"#4ade80","accentForeground":"#0f172a","controlBackground":"#4ade80","controlForeground":"#0f172a","focusRing":"#5eead4","overlay":"#17152b","fontFamily":"''M PLUS 1'', ''Inter'', sans-serif","borderRadius":"8px","flipAnimation":"rotateY","shadow":"0 0 30px rgba(74,222,128,0.2), inset 0 1px 0 rgba(255,255,255,0.05)"}'::jsonb),
    ('ocean-calm', '{"background":"linear-gradient(180deg, #e0f7fa 0%, #b2ebf2 100%)","contentSurface":"#e0f7fa","foreground":"#003b49","mutedForeground":"#285c66","border":"#4f6f76","accent":"#07566b","accentForeground":"#ffffff","controlBackground":"#07566b","controlForeground":"#ffffff","focusRing":"#07566b","overlay":"#e0f7fa","fontFamily":"''Zen Kaku Gothic New'', ''Noto Sans JP'', sans-serif","borderRadius":"28px","flipAnimation":"rotateX","shadow":"0 12px 48px rgba(7,86,107,0.14)"}'::jsonb),
    ('gold-calligraphy', '{"background":"linear-gradient(145deg, #1a1a1a 0%, #2d2d2d 100%)","contentSurface":"#1a1a1a","foreground":"#f5e6c8","mutedForeground":"#d6c7aa","border":"#a78f61","accent":"#e6c36a","accentForeground":"#1a1a1a","controlBackground":"#f5e6c8","controlForeground":"#1a1a1a","focusRing":"#ffd978","overlay":"#1a1a1a","fontFamily":"''Shippori Mincho'', ''Noto Serif JP'', serif","borderRadius":"4px","flipAnimation":"rotateY","shadow":"0 4px 20px rgba(230,195,106,0.22), inset 0 1px 0 rgba(230,195,106,0.12)"}'::jsonb)
) AS semantic(slug, config)
WHERE theme.slug = semantic.slug;
